logger = logging.getLogger(__name__)


class FamilyTaskViewSet(FeatureRequiredMixin, viewsets.ModelViewSet):
    required_feature = "organize"
    serializer_class = FamilyTaskSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self) -> QuerySet[FamilyTask]:
        user = cast(User, self.request.user)
        queryset = FamilyTask.objects.filter(
            family_id__in=get_accessible_family_ids(user)
        ).select_related("family", "assigned_to", "created_by", "linked_event")
        bucket = self.request.query_params.get("bucket")
        now = timezone.now()
        if bucket == "today":
            return queryset.filter(
                status=FamilyTask.Status.PENDING,
                due_at__isnull=False,
                due_at__date=timezone.localdate(now),
            )
        if bucket == "overdue":
            return queryset.filter(
                status=FamilyTask.Status.PENDING,
                due_at__lt=now,
            )
        if bucket == "this_week":
            return queryset.filter(
                status=FamilyTask.Status.PENDING,
                due_at__isnull=False,
                due_at__gte=now,
                due_at__lte=now + timedelta(days=7),
            )
        return queryset

    @action(detail=False, methods=["post"], url_path="create-from-household-action")
    def create_from_household_action(self, request):
        serializer = HouseholdActionTaskSerializer(
            data=request.data, context=self.get_serializer_context()
        )
        serializer.is_valid(raise_exception=True)
        family = get_default_family_for_user(request.user)
        if family is None:
            return Response(
                {"detail": "No active family found for this user."},
                status=status.HTTP_400_BAD_REQUEST,
            )
        task = create_task_from_household_action(
            family=family,
            title=serializer.validated_data["title"],
            notes=serializer.validated_data.get("notes", ""),
            due_at=serializer.validated_data.get("due_at"),
            assigned_to=serializer.validated_data.get("assigned_to"),
            linked_event=serializer.validated_data.get("linked_event"),
            created_by=request.user,
            source_client_app=getattr(request, "client_app", "house"),
        )
        response_serializer = self.get_serializer(task)
        return Response(response_serializer.data, status=status.HTTP_201_CREATED)


class ChoreProgramViewSet(FeatureRequiredMixin, viewsets.ModelViewSet):
    required_feature = "organize"
    serializer_class = ChoreProgramSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self) -> QuerySet[ChoreProgram]:
        user = cast(User, self.request.user)
        return ChoreProgram.objects.filter(
            family_id__in=get_accessible_family_ids(user)
        ).select_related("family", "assigned_to", "created_by")

    def perform_create(self, serializer):
        with transaction.atomic():
            program = serializer.save()
            materialize_chore_program(program)

    @action(detail=True, methods=["post"])
    def materialize(self, request, pk=None):
        tasks = materialize_chore_program(self.get_object())
        return Response(
            FamilyTaskSerializer(
                tasks, many=True, context=self.get_serializer_context()
            ).data
        )


class InboxCaptureViewSet(FeatureRequiredMixin, viewsets.ModelViewSet):
    required_feature = "organize"
    serializer_class = InboxCaptureSerializer
    permission_classes = [permissions.IsAuthenticated]
    parser_classes = [JSONParser, FormParser, MultiPartParser]

    def get_queryset(self) -> QuerySet[InboxCapture]:
        user = cast(User, self.request.user)
        queryset = InboxCapture.objects.filter(
            family_id__in=get_accessible_family_ids(user)
        ).select_related(
            "family",
            "created_by",
            "converted_task",
            "converted_grocery_list",
        )
        status_filter = self.request.query_params.get("status")
        if status_filter:
            queryset = queryset.filter(status=status_filter)
        return queryset

    @action(detail=False, methods=["post"], url_path="task-photo")
    def task_photo(self, request, *args, **kwargs):
        serializer = TaskPhotoCaptureSerializer(
            data=request.data, context=self.get_serializer_context()
        )
        serializer.is_valid(raise_exception=True)

        family = get_default_family_for_user(request.user)
        if family is None:
            return Response(
                {"detail": "No active family found for this user."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        try:
            capture = InboxCapture.objects.create(
                family=family,
                created_by=request.user,
                capture_type=InboxCapture.CaptureType.PHOTO,
                status=InboxCapture.Status.CAPTURED,
                raw_text=serializer.validated_data.get("raw_text", ""),
                raw_payload=serializer.validated_data.get("raw_payload", {}),
                source_client_app=getattr(request, "client_app", ""),
                photo=serializer.validated_data["photo"],
            )
        except Exception:
            logger.error(
                "Unable to create task photo capture.",
                exc_info=True,
                **build_task_photo_log_context(
                    operation="task_photo_create_capture",
                    user=request.user,
                    family=family,
                ),
            )
            return Response(
                {"detail": "We couldn't start task extraction right now."},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

        result = TaskPhotoExtractionService.process_capture(capture)
        if not result["success"]:
            if capture.photo:
                capture.photo.delete(save=False)
            capture.delete()
            return Response(
                {"detail": result["error"]},
                status=result.get("status_code", status.HTTP_400_BAD_REQUEST),
            )

        capture.refresh_from_db()
        return Response(
            self.get_serializer(capture).data, status=status.HTTP_201_CREATED
        )

    @action(detail=True, methods=["post"], url_path="create-tasks")
    def create_tasks(self, request, pk=None):
        capture = self.get_object()
        serializer = TaskSuggestionsCreateSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        try:
            created_tasks = create_tasks_from_capture(
                capture,
                reviewed_tasks=serializer.validated_data["tasks"],
            )
        except TaskCaptureCreateError as exc:
            logger.warning(
                "Unable to create tasks from capture: %s",
                exc.detail,
                **build_task_photo_log_context(
                    operation="task_photo_create_tasks",
                    capture=capture,
                    user=request.user,
                    family=capture.family,
                ),
            )
            return Response({"detail": exc.detail}, status=status.HTTP_400_BAD_REQUEST)
        except Exception:
            logger.error(
                "Unable to create tasks from capture.",
                exc_info=True,
                **build_task_photo_log_context(
                    operation="task_photo_create_tasks",
                    capture=capture,
                    user=request.user,
                    family=capture.family,
                ),
            )
            return Response(
                {"detail": "Unable to create tasks from capture."},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

        capture.refresh_from_db()
        response = self.get_serializer(capture).data
        response["tasks"] = FamilyTaskSerializer(
            created_tasks, many=True, context=self.get_serializer_context()
        ).data
        return Response(response, status=status.HTTP_201_CREATED)

    @action(detail=True, methods=["post"])
    def convert(self, request, pk=None):
        capture = self.get_object()
        serializer = CaptureConversionSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)
        if serializer.validated_data["target_kind"] == "grocery_list":
            grocery_list = convert_capture_to_grocery_list(
                capture,
                name=serializer.validated_data.get("title"),
                description=serializer.validated_data.get("notes", ""),
                owner=request.user,
            )
            payload = self.get_serializer(capture).data
            payload["grocery_list"] = GroceryListSummarySerializer(grocery_list).data
            return Response(payload)

        task = convert_capture_to_task(
            capture,
            title=serializer.validated_data.get("title"),
            notes=serializer.validated_data.get("notes", ""),
        )
        response_serializer = self.get_serializer(capture)
        payload = response_serializer.data
        payload["task"] = FamilyTaskSerializer(
            task, context=self.get_serializer_context()
        ).data
        return Response(payload)

    @action(detail=True, methods=["post"])
    def dismiss(self, request, pk=None):
        capture = dismiss_capture(self.get_object())
        serializer = self.get_serializer(capture)
        return Response(serializer.data)


class OrganizeDashboardView(FeatureRequiredMixin, APIView):
    required_feature = "organize"
    permission_classes = [IsAuthenticated]

    def get(self, request):
        payload_started_at = perf_counter()
        family_id = request.query_params.get("family_id")
        payload = get_dashboard_payload(
            request.user, request=request, family_id=family_id
        )
        payload_build_ms = (perf_counter() - payload_started_at) * 1000
        serialization_started_at = perf_counter()
        lists_payload = GroceryListSummarySerializer(payload["lists"], many=True).data
        response_payload = {
            "today": FamilyTaskSerializer(
                payload["today"], many=True, context={"request": request}
            ).data,
            "this_week": FamilyTaskSerializer(
                payload["this_week"], many=True, context={"request": request}
