logger = logging.getLogger(__name__)


def build_task_photo_log_context(
    *,
    operation: str,
    capture: InboxCapture | None = None,
    user: User | None = None,
    family: FamilyGroup | None = None,
) -> dict[str, Any]:
    if capture is not None:
        user = user or capture.created_by
        family = family or capture.family
    return {
        "extra": {
            "operation": operation,
            "capture_id": getattr(capture, "id", None),
            "user_id": getattr(user, "id", None),
            "family_id": getattr(family, "id", None),
        }
    }


def get_default_family_for_user(user: User) -> FamilyGroup | None:
    profile = getattr(user, "profile", None)
    primary_family = getattr(profile, "primary_family", None)
    if primary_family is not None:
        return primary_family

    membership = (
        FamilyMembership.objects.filter(user=user, is_active=True)
        .select_related("family")
        .first()
    )
    if membership:
        return membership.family
    return None


def get_accessible_family_ids(user: User) -> list[UUID]:
    return list(
        FamilyMembership.objects.filter(user=user, is_active=True).values_list(
            "family_id", flat=True
        )
    )


def get_client_app_context(
    request=None, source_client_app: str | None = None
) -> dict[str, Any]:
    request_client_app = getattr(request, "client_app", None) if request else None
    client_app = canonicalize_client_app(
        request_client_app or source_client_app, default=ClientApp.COORD
    )
    return {
        "client_app": client_app,
        "owning_app": ClientApp.ORGANIZE,
        "source_client_app": source_client_app or "",
        "available_apps": [choice[0] for choice in ClientApp.choices],
        "deep_links": {
            app: build_client_app_link(app, "/") for app, _label in ClientApp.choices
        },
    }


def normalize_capture_payload(
    *, capture_type: str, raw_text: str = "", raw_payload: dict[str, Any] | None = None
) -> dict[str, Any]:
    payload = dict(raw_payload or {})
    lines = [line.strip() for line in raw_text.splitlines() if line.strip()]
    if "suggested_items" not in payload and lines:
        payload["suggested_items"] = lines
    payload.setdefault("suggested_title", lines[0] if lines else "Inbox item")
    payload.setdefault(
        "suggested_kind",
        "grocery_list" if capture_type == InboxCapture.CaptureType.PHOTO else "task",
    )
    if "preview_text" not in payload:
        if lines:
            payload["preview_text"] = " | ".join(lines[:2])[:140]
        elif capture_type == InboxCapture.CaptureType.PHOTO:
            payload["preview_text"] = "Photo capture ready for review"
        elif capture_type == InboxCapture.CaptureType.EMAIL:
            payload["preview_text"] = "Email capture ready for review"
    return payload


class TaskPhotoProcessingError(ValueError):
    pass


class TaskCaptureCreateError(ValueError):
    def __init__(self, detail: str):
        super().__init__(detail)
        self.detail = detail


class TaskPhotoExtractionService:
    FEATURE_FLAG_KEY = "enable-ai-task-extraction"
    DEFAULT_MAX_IMAGE_SIZE_BYTES = 10 * 1024 * 1024
    DEFAULT_MAX_IMAGE_DIMENSION = 4096
    DEFAULT_MAX_IMAGE_PIXELS = 25_000_000
    SAFE_EXTRACTION_ERROR_DETAIL = "We couldn't process that photo right now."
    SAFE_OVERSIZE_ERROR_DETAIL = "Image is too large to process."

    EXTRACTION_PROMPT = """
    You are an AI assistant specialized in extracting family task lists from photos.

    The user has uploaded a photo of handwritten notes, a whiteboard, or a to-do list.
    Identify the task items that should become actionable tasks.

    Return ONLY valid JSON with this shape:
    {
        "suggested_kind": "tasks",
        "suggested_tasks": [
            {
                "title": "Task title",
                "notes": "Optional notes or context",
                "confidence": 0.95
            }
        ],
        "preview_text": "Short human-readable preview",
        "processing_notes": "Optional notes about uncertain items"
    }

    Guidelines:
    - Prefer one task per item, even when the list is messy.
    - Keep titles short and actionable.
    - If a line is unclear, include your best guess and lower confidence.
    - If no task list is visible, return an empty suggested_tasks array.
    - Do not include extra commentary outside the JSON object.
    """

    @classmethod
    def _is_feature_enabled(cls, user: User | None) -> bool:
        if not getattr(settings, "FEATURE_FLAGS_ENABLED", False):
            return True

        family = get_default_family_for_user(user) if user is not None else None
        try:
            from openfeature.api import get_client
            from openfeature.evaluation_context import EvaluationContext

            evaluation_context = EvaluationContext(
                targeting_key=str(getattr(user, "id", "anonymous")),
                attributes={
                    "email": getattr(user, "email", ""),
                    "username": user.get_username() if user else "",
                },
            )
            client = get_client()
            return client.get_boolean_value(
                cls.FEATURE_FLAG_KEY,
                False,
                evaluation_context,
            )
        except Exception as exc:  # pragma: no cover - defensive guard
            logger.warning(
                "Task photo feature flag check failed, defaulting to disabled: %s",
                exc,
                **build_task_photo_log_context(
                    operation="task_photo_feature_flag_check",
                    user=user,
                    family=family,
                ),
            )
            return False

    @classmethod
    def _load_photo_bytes(cls, capture: InboxCapture) -> tuple[bytes, str, str]:
        if not capture.photo:
            raise TaskPhotoProcessingError("A photo is required for task extraction")

        with capture.photo.open("rb"):
            content = capture.photo.read()

        if not content:
            raise TaskPhotoProcessingError("Uploaded photo is empty")

        max_image_size = getattr(
            settings, "MAX_IMAGE_SIZE", cls.DEFAULT_MAX_IMAGE_SIZE_BYTES
        )
        if len(content) > max_image_size:
            raise TaskPhotoProcessingError(cls.SAFE_OVERSIZE_ERROR_DETAIL)

        max_dimension = getattr(
            settings, "TASK_PHOTO_MAX_IMAGE_DIMENSION", cls.DEFAULT_MAX_IMAGE_DIMENSION
        )
        max_pixels = getattr(
            settings, "TASK_PHOTO_MAX_IMAGE_PIXELS", cls.DEFAULT_MAX_IMAGE_PIXELS
        )
        try:
            with warnings.catch_warnings():
                warnings.simplefilter("error", Image.DecompressionBombWarning)
                with Image.open(io.BytesIO(content)) as image:
                    width, height = image.size
                    if width > max_dimension or height > max_dimension:
                        raise TaskPhotoProcessingError(cls.SAFE_OVERSIZE_ERROR_DETAIL)
                    if width * height > max_pixels:
                        raise TaskPhotoProcessingError(cls.SAFE_OVERSIZE_ERROR_DETAIL)
                    image.verify()
                    content_type = Image.MIME.get(image.format or "", "image/jpeg")
        except (Image.DecompressionBombError, Image.DecompressionBombWarning) as exc:
            raise TaskPhotoProcessingError(cls.SAFE_OVERSIZE_ERROR_DETAIL) from exc
        except TaskPhotoProcessingError:
            raise
        except Exception as exc:
            raise TaskPhotoProcessingError("Uploaded photo is invalid.") from exc

        if not content_type:
            guessed = mimetypes.guess_type(capture.photo.name or "")[0]
            content_type = guessed or "image/jpeg"

        return content, content_type, capture.photo.name or "task-photo"

    @classmethod
    def _build_data_url(cls, content: bytes, content_type: str) -> str:
        encoded = base64.b64encode(content).decode("utf-8")
        return f"data:{content_type};base64,{encoded}"

    @classmethod
    def _strip_code_fence(cls, response_text: str) -> str:
        response_text = response_text.strip()
        if response_text.startswith("```"):
            lines = response_text.splitlines()
            if len(lines) >= 3:
                response_text = "\n".join(lines[1:-1]).strip()
        return response_text

    @classmethod
    def _extract_task_payload(cls, content: bytes, content_type: str) -> dict[str, Any]:
        import aisuite as ai

        client = ai.Client()
        response = client.chat.completions.create(
            model="openai:gpt-4o-mini",
            messages=[
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": cls.EXTRACTION_PROMPT},
                        {
                            "type": "image_url",
                            "image_url": {
                                "url": cls._build_data_url(content, content_type)
                            },
                        },
                    ],
                }
            ],
            temperature=0.2,
        )

        response_text = cls._strip_code_fence(
            cast(str, response.choices[0].message.content or "")
        )
        try:
            parsed = cast(dict[str, Any], json.loads(response_text))
        except json.JSONDecodeError:
            return {
                "suggested_kind": "tasks",
                "suggested_tasks": [],
                "preview_text": "Photo capture ready for review",
                "processing_notes": response_text,
            }

        return parsed

    @classmethod
    def _normalize_payload(cls, extracted: dict[str, Any]) -> dict[str, Any]:
        raw_tasks = extracted.get("suggested_tasks") or extracted.get("tasks") or []
        normalized_tasks: list[dict[str, Any]] = []

        for raw_task in raw_tasks:
            if isinstance(raw_task, str):
                title = raw_task.strip()
                notes = ""
                confidence = None
            elif isinstance(raw_task, dict):
                title = str(raw_task.get("title") or raw_task.get("name") or "").strip()
                notes = str(
                    raw_task.get("notes") or raw_task.get("description") or ""
                ).strip()
                confidence = raw_task.get("confidence")
                if isinstance(confidence, dict):
                    confidence = confidence.get("task") or confidence.get("title")
            else:
                continue

            if not title:
                continue

            if confidence is not None and not isinstance(confidence, (int, float)):
                confidence = None

            normalized_tasks.append(
                {
                    "title": title,
                    "notes": notes,
                    "confidence": confidence,
                }
            )

        preview_text = str(extracted.get("preview_text") or "").strip()
        if not preview_text:
            if normalized_tasks:
                preview_text = " | ".join(
                    task["title"] for task in normalized_tasks[:2]
                )[:140]
            else:
                preview_text = "Photo capture ready for review"

        payload = {
            "suggested_kind": "tasks",
            "suggested_tasks": normalized_tasks,
            "preview_text": preview_text,
        }
        processing_notes = str(extracted.get("processing_notes") or "").strip()
        if processing_notes:
            payload["processing_notes"] = processing_notes
        return payload

    @classmethod
    def process_capture(cls, capture: InboxCapture) -> dict[str, Any]:
        if not cls._is_feature_enabled(capture.created_by):
            return {
                "success": False,
                "error": "Task photo extraction is not enabled for your account",
            }

        capture.status = InboxCapture.Status.PROCESSING
        capture.save(update_fields=["status", "updated_at"])

        try:
            content, content_type, _photo_name = cls._load_photo_bytes(capture)
            extracted = cls._extract_task_payload(content, content_type)
            normalized = cls._normalize_payload(extracted)
            capture.normalized_payload = normalized
            capture.status = InboxCapture.Status.NEEDS_REVIEW
            capture.save(update_fields=["normalized_payload", "status", "updated_at"])
            return {"success": True, "data": normalized}
        except TaskPhotoProcessingError as exc:
            logger.warning(
                "Task photo processing failed: %s",
                exc,
                **build_task_photo_log_context(
                    operation="task_photo_process_capture",
                    capture=capture,
                ),
            )
            capture.status = InboxCapture.Status.CAPTURED
            capture.save(update_fields=["status", "updated_at"])
            return {"success": False, "error": str(exc), "status_code": 400}
        except Exception as exc:
            logger.error(
                "Unexpected task photo extraction failure: %s",
                exc,
                exc_info=True,
                **build_task_photo_log_context(
                    operation="task_photo_process_capture",
                    capture=capture,
                ),
            )
            capture.status = InboxCapture.Status.CAPTURED
            capture.save(update_fields=["status", "updated_at"])
            return {
                "success": False,
                "error": cls.SAFE_EXTRACTION_ERROR_DETAIL,
                "status_code": 500,
            }


def create_task_from_household_action(
    *,
    family: FamilyGroup,
    title: str,
    source_client_app: str = ClientApp.HOUSE,
    due_at=None,
    notes: str = "",
    created_by: User | None = None,
    assigned_to: User | None = None,
    source_object=None,
    linked_event=None,
    task_kind: str = FamilyTask.TaskKind.MANUAL,
) -> FamilyTask:
    task = FamilyTask(
        family=family,
        title=title,
        notes=notes,
        due_at=due_at,
        created_by=created_by,
        assigned_to=assigned_to,
        source_client_app=canonicalize_client_app(source_client_app, default=""),
        linked_event=linked_event,
        task_kind=task_kind,
    )
    if source_object is not None:
        task.source_object = source_object
    task.save()
    return task


@transaction.atomic
def convert_capture_to_task(
    capture: InboxCapture,
    *,
    title: str | None = None,
    notes: str = "",
    assigned_to: User | None = None,
) -> FamilyTask:
    task = create_task_from_household_action(
        family=capture.family,
        title=title or capture.raw_text or "Inbox item",
        notes=notes or capture.raw_text,
        source_client_app=capture.source_client_app or ClientApp.ORGANIZE,
        created_by=capture.created_by,
        assigned_to=assigned_to,
        source_object=capture,
    )
    capture.converted_task = task
    capture.status = InboxCapture.Status.CONVERTED
    capture.save(update_fields=["converted_task", "status", "updated_at"])
    return task


@transaction.atomic
def convert_capture_to_grocery_list(
    capture: InboxCapture,
    *,
    name: str | None = None,
    description: str = "",
    owner: User | None = None,
) -> GroceryList:
    owner = owner or capture.created_by
    if owner is None:
        raise ValueError("Inbox capture cannot be converted without an owning user.")

    grocery_list = GroceryList.objects.create(
        family=capture.family,
        name=name
        or capture.normalized_payload.get("suggested_title")
        or "Shopping list",
        description=description or capture.raw_text or "",
        owner=owner,
        is_group=True,
    )

    items = [
        GroceryItem(
            grocery_list=grocery_list,
            name=item_name,
            position=position,
            created_by=owner,
        )
        for position, item_name in enumerate(
            capture.normalized_payload.get("suggested_items", []), start=1
        )
    ]
    if items:
        GroceryItem.objects.bulk_create(items)

    capture.converted_grocery_list = grocery_list
    capture.status = InboxCapture.Status.CONVERTED
    capture.save(update_fields=["converted_grocery_list", "status", "updated_at"])
    return grocery_list


@transaction.atomic
def create_tasks_from_capture(
    capture: InboxCapture,
    *,
    reviewed_tasks: list[dict[str, Any]],
) -> list[FamilyTask]:
    capture = InboxCapture.objects.select_for_update().get(pk=capture.pk)
    normalized_payload = dict(capture.normalized_payload or {})
    existing_task_ids = [
        str(task_id)
        for task_id in normalized_payload.get("created_task_ids", [])
        if isinstance(task_id, str)
    ]
    if capture.status == InboxCapture.Status.CONVERTED:
        existing_task_map = {
            str(task.id): task
            for task in FamilyTask.objects.filter(id__in=existing_task_ids)
        }
        existing_tasks = [
            existing_task_map[task_id]
            for task_id in existing_task_ids
            if task_id in existing_task_map
        ]
        if not existing_tasks and capture.converted_task_id:
            existing_tasks = [capture.converted_task] if capture.converted_task else []
        if existing_tasks:
            return existing_tasks
        raise TaskCaptureCreateError(
            "Tasks have already been created from this capture."
        )

    selected_tasks = [
        task
        for task in reviewed_tasks
        if task.get("selected", True) and str(task.get("title", "")).strip()
    ]
    if not selected_tasks:
        raise TaskCaptureCreateError("Select at least one task to create.")

    created_tasks: list[FamilyTask] = []
    for task_data in selected_tasks:
        created_tasks.append(
            create_task_from_household_action(
                family=capture.family,
                title=str(task_data["title"]).strip(),
                notes=str(task_data.get("notes") or "").strip(),
                source_client_app=capture.source_client_app or ClientApp.ORGANIZE,
                created_by=capture.created_by,
                source_object=capture,
            )
        )

    normalized_payload["reviewed_tasks"] = selected_tasks
    normalized_payload["created_task_ids"] = [str(task.id) for task in created_tasks]
    capture.converted_task = created_tasks[0]
    capture.normalized_payload = normalized_payload
    capture.status = InboxCapture.Status.CONVERTED
    capture.save(
        update_fields=[
            "converted_task",
            "normalized_payload",
            "status",
            "updated_at",
        ]
    )
    return created_tasks


def dismiss_capture(capture: InboxCapture) -> InboxCapture:
    capture.status = InboxCapture.Status.DISMISSED
    capture.save(update_fields=["status", "updated_at"])
    return capture


def get_dashboard_payload(
    user: User, request=None, family_id: str | None = None
) -> dict[str, Any]:
    started_at = perf_counter()
    now = timezone.now()
    local_now = timezone.localtime(now)
    today_start = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
    today_events_end = local_now.replace(
        hour=23, minute=59, second=59, microsecond=999999
    )
    family_ids = get_accessible_family_ids(user)
    tasks = (
        FamilyTask.objects.filter(family_id__in=family_ids)
        .select_related("family", "assigned_to", "created_by", "linked_event")
        .order_by("due_at", "created_at")
    )
    today_bucket_end = now + timedelta(days=1)
    week_end = now + timedelta(days=7)
    upcoming_events = (
        Event.secure.for_user(user, include_meta=False)
        .filter(end_time__gte=now)
        .order_by("start_time")
        .only("id", "title", "start_time", "end_time", "family_group_id")
    )[:6]
    today_events_qs = Event.secure.for_user(user, include_meta=False).filter(
        end_time__gte=today_start, start_time__lte=today_events_end
    )
    if family_id:
        today_events_qs = today_events_qs.filter(family_group_id=family_id)
    today_events = today_events_qs.order_by("start_time")
    dashboard_lists = list(
        GroceryList.objects.filter(family_id__in=family_ids)
        .only("id", "name", "updated_at", "list_type")
        .annotate(dashboard_item_count=Count("items", distinct=True))
        .order_by("-updated_at")
    )
    inbox_captures = (
        InboxCapture.objects.filter(
            family_id__in=family_ids,
            status__in=[
                InboxCapture.Status.CAPTURED,
                InboxCapture.Status.PROCESSING,
                InboxCapture.Status.NEEDS_REVIEW,
            ],
        )
        .select_related("created_by", "converted_task", "converted_grocery_list")
        .order_by("-created_at")
    )[:5]
    payload = {
        "today": tasks.filter(
            status=FamilyTask.Status.PENDING,
            due_at__isnull=False,
            due_at__gte=now,
            due_at__lte=today_bucket_end,
        ),
        "this_week": tasks.filter(
            status=FamilyTask.Status.PENDING,
            due_at__isnull=False,
            due_at__gt=today_bucket_end,
            due_at__lte=week_end,
        ),
        "overdue": tasks.filter(
            status=FamilyTask.Status.PENDING,
            due_at__lt=now,
        ),
        "today_events": today_events,
        "upcoming_events": upcoming_events,
        "grocery_lists": dashboard_lists,
        "lists": dashboard_lists,
        "inbox": inbox_captures,
        "client_app_context": get_client_app_context(request),
    }
    logger.info(
        "Organize dashboard payload built in %.2fms",
        (perf_counter() - started_at) * 1000,
        extra={
            "client_app": getattr(request, "client_app", None),
            "family_count": len(family_ids),
        },
    )
    return payload


@transaction.atomic
def materialize_chore_program(program: ChoreProgram, *, start=None) -> list[FamilyTask]:
    # Re-fetch with row lock to prevent concurrent materialization races
    program = ChoreProgram.objects.select_for_update().get(pk=program.pk)

    if not program.is_active:
        return []

    start = start or timezone.now()
    period_map = {
        ChoreProgram.Frequency.DAILY: 1,
        ChoreProgram.Frequency.WEEKLY: 7,
        ChoreProgram.Frequency.BIWEEKLY: 14,
        ChoreProgram.Frequency.MONTHLY: 30,
    }
    period_days = period_map[ChoreProgram.Frequency(program.frequency)]
    period = timedelta(days=period_days)

    # Compute stable window boundaries so repeat calls are idempotent.
    # Anchor to rotation_anchor_date if available, otherwise use today.
    anchor = program.rotation_anchor_date or timezone.localdate(start)
    today = timezone.localdate(start)
    # Find the start of the current window relative to the anchor
    days_since_anchor = (today - anchor).days
    current_window_offset = (days_since_anchor // period_days) * period_days
    window_start = anchor + timedelta(days=current_window_offset)

    window_boundaries = [window_start, window_start + period]
    tasks: list[FamilyTask] = []
    rotation_increments = 0

    for win_start in window_boundaries:
        win_end = win_start + timedelta(days=period_days - 1)
        # Use window midpoint as a stable due_at for idempotent get_or_create
        due_at = timezone.make_aware(
            dt_datetime.combine(win_start, dt_datetime.min.time())
        ) + timedelta(days=period_days // 2)

        assigned_to = program.assigned_to
        if (
            program.assignment_mode == ChoreProgram.AssignmentMode.ROUND_ROBIN
            and program.rotation_member_ids
        ):
            member_ids = list(program.rotation_member_ids)
            idx = (program.current_rotation_index + rotation_increments) % len(
                member_ids
            )
            assignee_id = member_ids[idx]
            assigned_to = User.objects.filter(id=assignee_id).first()

        task, created = FamilyTask.objects.get_or_create(
            family=program.family,
            title=program.title,
            task_kind=FamilyTask.TaskKind.CHORE,
            chore_program=program,
            window_starts_on=win_start,
            defaults={
                "notes": program.notes,
                "due_at": due_at,
                "window_ends_on": win_end,
                "created_by": program.created_by,
                "assigned_to": assigned_to,
                "source_client_app": ClientApp.ORGANIZE,
            },
        )
        if created:
            tasks.append(task)
            if (
                program.assignment_mode == ChoreProgram.AssignmentMode.ROUND_ROBIN
                and program.rotation_member_ids
            ):
                rotation_increments += 1

    if tasks:
        if rotation_increments:
            ChoreProgram.objects.filter(pk=program.pk).update(
                current_rotation_index=F("current_rotation_index")
                + rotation_increments,
            )
        ChoreProgram.objects.filter(pk=program.pk).update(
            last_materialized_for=timezone.localdate(tasks[-1].due_at or start),
        )
    return tasks
